fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    let mut result = Vec::with_capacity(input.len());
    for (a, b) in input {
        let moves = if a == b {
            0
        } else if b > a {
            // We need to increase from a to b.
            // If the difference is odd, one odd-increment move suffices.
            // If it's even, we need two odd-increment moves (odd+odd = even).
            let delta = b - a;
            if delta % 2 != 0 { 1 } else { 2 }
        } else {
            // b < a: we need to decrease from a to b.
            // If the difference is even, one even-decrement move suffices.
            // If it's odd, we need one odd-increment and one even-decrement move (2 moves).
            let delta = a - b;
            if delta % 2 == 0 { 1 } else { 2 }
        };
        result.push(moves);
    }
    result
}

