        // even difference -> 1 move; odd difference -> 2 moves
        assert_eq!(solve(vec![(10, 4), (10, 5)]), vec![1, 2]);
        assert_eq!(solve(vec![(6, 2), (6, 3)]), vec![1, 2]);
